{"command":"cd /testbed/release-mgmt/release/RB-42 && python3 - <<'PY'
import hashlib, json, os

d = os.getcwd()
man = json.load(open("manifest.json"))
entries = man["artifacts"]
print("manifest bundle_id:", man.get("bundle_id"), "| entries:", len(entries))

paths = [e["path"] for e in entries]
print("duplicate paths in manifest:", [p for p in set(paths) if paths.count(p) > 1] or "none")

def sha(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(65536), b""):
            h.update(b)
    return h.hexdigest()

absent, bad, ok = [], [], []
for e in entries:
    fp = os.path.join(d, e["path"])
    if not os.path.exists(fp):
        absent.append(e["path"]); continue
    (ok if sha(fp) == e.get("sha256") else bad).append(e["path"])

print("verified:", len(ok), "| hash-mismatch:", len(bad), "| absent:", len(absent))
for p in bad: print("  BAD   ", p)
for p in absent: print("  ABSENT", p)

# extra files on disk not listed in the manifest
on_disk = set()
for root, _, files in os.walk(d):
    for f in files:
        rel = os.path.relpath(os.path.join(root, f), d)
        if rel != "manifest.json":
            on_disk.add(rel.replace(os.sep, "/"))
print("files on disk (excl manifest):", len(on_disk))
print("extras not in manifest:", sorted(on_disk - set(paths)) or "none")
print("complete =", len(ok) == len(entries) and not bad and not absent)
PY"}

